const I18N_SKIP='script,style,textarea,[contenteditable="true"],[data-noi18n],#cmtBody,.ttitle,.tdtitle,.tdbody,.tcard .tbody,.ttags';
function i18nSkip(el){
  try{return !!(el&&el.closest&&el.closest(I18N_SKIP));}catch(e){return false;}}
function i18nWordsOk(el){
  /* 표 본문 칸은 사용자 데이터(매체명 · 상품명 …)라 낱말 대체를 하지 않는다 */
  try{return !(el&&el.closest&&el.closest('tbody td,.sheet td,select option'));}catch(e){return true;}}
function trTextNode(t){
  const v=t.nodeValue;
  if(!v||!I18N_HANGUL.test(v))return;
  const p=t.parentNode;if(!p||i18nSkip(p))return;
  let out=trText(v,i18nWordsOk(p));
  if(out!==v){
    /* 한국어는 조사가 앞 낱말(굵은 글씨 등)에 붙어 있다 — 영어가 되면 사이를 띄운다 */
    const ps=t.previousSibling,ns=t.nextSibling;
    if(/^[A-Za-z(]/.test(out)&&!/^\s/.test(v)&&ps&&ps.nodeType===1&&/[A-Za-z0-9)%]$/.test(ps.textContent||''))out=' '+out;
    if(/[A-Za-z0-9.,:;)]$/.test(out)&&!/\s$/.test(v)&&ns&&ns.nodeType===1&&/^[A-Za-z0-9(\uac00-\ud7a3]/.test(ns.textContent||''))out+=' ';
    if(t.__ko==null)t.__ko=v;t.nodeValue=out;}}
function trAttrs(el){
  if(!el||!el.getAttribute)return;
  for(const a of I18N_ATTRS){
    const v=el.getAttribute(a);
    if(!v||!I18N_HANGUL.test(v))continue;
    const out=v.split('\n').map(x=>trText(x,true)).join('\n');
    if(out!==v){
      if(!el.__koA)el.__koA={};
      if(el.__koA[a]==null)el.__koA[a]=v;
      I18N_BUSY=true;try{el.setAttribute(a,out);}finally{I18N_BUSY=false;}}}}
function trNode(root){
  if(LANG!=='en'||!root)return;
  if(root.nodeType===3){trTextNode(root);return;}
  if(root.nodeType!==1&&root.nodeType!==11)return;
  if(root.nodeType===1){if(i18nSkip(root))return;trAttrs(root);}
  try{trBlocks(root);}catch(e){}
  const w=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT,{
    acceptNode:n=>{
      if(n.nodeType===1)return n.matches&&n.matches(I18N_SKIP)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT;
      return NodeFilter.FILTER_ACCEPT;}});
  let n;
  while((n=w.nextNode())){
    if(n.nodeType===3)trTextNode(n);else trAttrs(n);}}
/* 원문으로 되돌리기 (한국어로 바꿀 때) */
function i18nRestore(root){
  const w=document.createTreeWalker(root||document.body,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT);
  let n;
  while((n=w.nextNode())){
    if(n.nodeType===3){if(n.__ko!=null){n.nodeValue=n.__ko;n.__ko=null;}}
    else if(n.__koA){for(const a in n.__koA)n.setAttribute(a,n.__koA[a]);n.__koA=null;}}}
/* 그리는 순간 옮기기 — innerHTML · insertAdjacentHTML · textContent · 속성 */
(function i18nHooks(){
  try{
    /* v78 — 여기서 바로 옮긴 부분을 관찰자가 한 번 더 훑지 않게 한다 (영어 화면 다시 그리기가 두 배로 걸렸다).
       ① 넣기 전에 쌓여 있던 기록은 관찰자가 하던 그대로 먼저 처리하고
       ② 넣고 옮긴 뒤 생긴 기록 중 **이 요소에 붙은 것(방금 옮긴 자식들)** 만 버린다 */
    const ih=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');
    Object.defineProperty(Element.prototype,'innerHTML',{configurable:true,enumerable:ih.enumerable,
      get(){return ih.get.call(this);},
      set(v){
        const go=LANG==='en'&&!I18N_BUSY&&I18N_HANGUL.test(v||'');
        if(go)i18nFlush();
        ih.set.call(this,v);
        if(go){trNode(this);i18nDrop(this);}}});
    const iah=Element.prototype.insertAdjacentHTML;
    Element.prototype.insertAdjacentHTML=function(pos,html){
      const go=LANG==='en'&&I18N_HANGUL.test(html||'');
      const p=go?((pos==='beforebegin'||pos==='afterend')?this.parentNode:this):null;
      if(p)i18nFlush();
      iah.call(this,pos,html);
      if(p){trNode(p);i18nDrop(p);}};
    const tc=Object.getOwnPropertyDescriptor(Node.prototype,'textContent');
    Object.defineProperty(Node.prototype,'textContent',{configurable:true,enumerable:tc.enumerable,
      get(){return tc.get.call(this);},
      set(v){
        if(LANG==='en'&&!I18N_BUSY&&v!=null&&I18N_HANGUL.test(String(v))
           &&(this.nodeType===1?!i18nSkip(this):!(this.parentNode&&i18nSkip(this.parentNode)))){
          const out=trText(String(v),this.nodeType===1?i18nWordsOk(this):true);
          tc.set.call(this,out);
          if(out!==v){const t=this.nodeType===3?this:this.firstChild;if(t&&t.nodeType===3)t.__ko=String(v);}
          return;}
        tc.set.call(this,v);}});
    const sa=Element.prototype.setAttribute;
    Element.prototype.setAttribute=function(a,v){
      if(LANG==='en'&&!I18N_BUSY&&(a==='title'||a==='placeholder'||a==='aria-label'||a==='alt')
         &&v!=null&&I18N_HANGUL.test(String(v))&&!i18nSkip(this)){
        const out=String(v).split('\n').map(x=>trText(x,true)).join('\n');
        if(out!==v){if(!this.__koA)this.__koA={};this.__koA[a]=String(v);}
        return sa.call(this,a,out);}
      return sa.call(this,a,v);};
    for(const a of ['title','placeholder']){
      const proto=a==='title'?HTMLElement.prototype:HTMLInputElement.prototype;
      const d=Object.getOwnPropertyDescriptor(proto,a);if(!d||!d.set)continue;
      Object.defineProperty(proto,a,{configurable:true,enumerable:d.enumerable,get(){return d.get.call(this);},
        set(v){if(LANG==='en'&&v!=null&&I18N_HANGUL.test(String(v))&&!i18nSkip(this)){
            const out=String(v).split('\n').map(x=>trText(x,true)).join('\n');
            if(!this.__koA)this.__koA={};this.__koA[a]=String(v);d.set.call(this,out);return;}
          d.set.call(this,v);}});}
    const ta=HTMLTextAreaElement.prototype,tp=Object.getOwnPropertyDescriptor(ta,'placeholder');
    if(tp&&tp.set)Object.defineProperty(ta,'placeholder',{configurable:true,get(){return tp.get.call(this);},
      set(v){tp.set.call(this,LANG==='en'?trText(v,true):v);}});
  }catch(e){console.warn('i18n hooks',e);}
  /* 알림창 */
  const wrap=f=>function(m,...r){return f.call(window,LANG==='en'?trText(String(m==null?'':m),true):m,...r);};
  try{window.alert=wrap(window.alert);window.confirm=wrap(window.confirm);window.prompt=wrap(window.prompt);}catch(e){}
})();
/* 나머지 경로(appendChild · createTextNode …)는 관찰자가 뒤따라 옮긴다 */
function i18nApply(recs){
  if(LANG!=='en')return;
  for(const r of recs){
    if(r.type==='childList')r.addedNodes.forEach(n=>trNode(n));
    else if(r.type==='characterData')trTextNode(r.target);
    else if(r.type==='attributes'&&!I18N_BUSY)trAttrs(r.target);}}
const I18N_MO=new MutationObserver(i18nApply);
/* 관찰자에 쌓인 기록 — 함수로 감싼다: 훅(위)이 이 파일의 const 보다 먼저 돌 수 있다 (TDZ) */
function i18nTake(){try{return window.__i18nOn?I18N_MO.takeRecords():[];}catch(e){return [];}}
function i18nFlush(){const recs=i18nTake();if(recs.length)i18nApply(recs);}
function i18nDrop(target){
  const recs=i18nTake();if(!recs.length)return;
  const rest=recs.filter(r=>r.target!==target);
  if(rest.length)i18nApply(rest);}
/* 한국어 화면에서는 아예 관찰하지 않는다 (v78) — 예전에는 모든 변경을 기록만 쌓고 버렸다 */
function i18nWatch(){
  try{
    if(LANG==='en'){if(!window.__i18nOn){I18N_MO.observe(document.body,{subtree:true,childList:true,characterData:true,
      attributes:true,attributeFilter:I18N_ATTRS});window.__i18nOn=true;}}
    else if(window.__i18nOn){I18N_MO.disconnect();window.__i18nOn=false;}
  }catch(e){}}
/* ---------- 언어 바꾸기 ---------- */
function setLang(v,opt){
  v=v==='en'?'en':'ko';
  const changed=v!==LANG;
  LANG=v;
  try{if(!(opt&&opt.noSave))localStorage.setItem(LANG_KEY,v);}catch(e){}
  document.documentElement.lang=v;
  WD=(v==='en'?WD_EN:WD_KO).slice();
  ['langSel','gateLang'].forEach(id=>{const e=document.getElementById(id);if(e&&e.value!==v)e.value=v;});
  try{if(typeof paintLangBtn==='function')paintLangBtn();}catch(e){}
  if(!changed&&!(opt&&opt.force))return;
  /* 영어면 관찰을 켜고, 한국어면 끈다 (v78) */
  if(document.body)i18nWatch();
  if(v==='ko'){restoreBlocks(document.body);i18nRestore(document.body);}
  /* 코드 안에서 만든 문장(L() · 요일 · 달력)은 다시 그려야 바뀐다 */
  try{if(typeof renderEverything==='function')renderEverything();}catch(e){}
  try{if(typeof renderCampForm==='function')renderCampForm();}catch(e){}
  try{if(typeof applyRole==='function')applyRole();}catch(e){}
  try{if(typeof renderBrand==='function')renderBrand();}catch(e){}
  try{if(typeof paintSaved==='function')paintSaved();}catch(e){}
  try{if(typeof cloudStateIdle==='function')cloudStateIdle();}catch(e){}
  try{if(typeof renderCmtTools==='function')renderCmtTools();}catch(e){}
  if(v==='en')trNode(document.body);
  try{if(typeof fitTabs==='function')fitTabs();}catch(e){}
  try{if(typeof syncStick==='function')syncStick();}catch(e){}
  try{if(typeof syncUrl==='function')syncUrl();}catch(e){}}
(function initLang(){
  const go=()=>{
    document.documentElement.lang=LANG;
    ['langSel','gateLang'].forEach(id=>{const sel=document.getElementById(id);
      if(sel){sel.value=LANG;sel.onchange=()=>setLang(sel.value);}});
    /* 상단 언어 단추 (v72) — 누르면 목록, 고르면 바꾸고 닫는다 */
    const lb=document.getElementById('langBtn'),lm=document.getElementById('langMenu');
    if(lb&&lm){
      const close=()=>{lm.classList.add('hidden');lb.setAttribute('aria-expanded','false');};
      lb.onclick=e=>{e.stopPropagation();const open=lm.classList.contains('hidden');
        lm.classList.toggle('hidden',!open);lb.setAttribute('aria-expanded',open?'true':'false');};
      lm.querySelectorAll('[data-lang]').forEach(b=>b.onclick=e=>{e.stopPropagation();close();setLang(b.dataset.lang);});
      document.addEventListener('click',e=>{if(!lm.classList.contains('hidden')&&!lm.contains(e.target))close();});
      document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});}
    try{if(typeof paintLangBtn==='function')paintLangBtn();}catch(e){}
    i18nWatch();
    /* 영어로 여는 경우 — 첫 화면은 번역기가 붙기 전에 한국어로 그려졌으므로
       한 번 더 그려서 글자 폭을 재는 부분(진행 막대 이름 · 열 너비 …)이 영어를 재게 한다 */
    if(LANG==='en'){trNode(document.body);setLang('en',{force:true,noSave:true});}};
  document.readyState==='loading'?addEventListener('DOMContentLoaded',go):go();
})();
/* 엑셀 리포트용 — 셀 · 시트 이름 (사용자 데이터 보호를 위해 낱말 대체는 쓰지 않는다) */
const trXL=s=>LANG==='en'?trText(s,false):s;
